the config is loacated at C:\Users\(URUSERNAMEDUMMY)\.config\opencode

$ErrorActionPreference = "Stop"
$chunkTimeoutMs = 2147483647
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"

# Close OpenCode processes if any are still alive.
Get-Process -ErrorAction SilentlyContinue | Where-Object {
  $_.ProcessName -like "*opencode*" -or
  ($(try { $_.Path } catch { "" }) -like "*opencode*")
} | Stop-Process -Force -ErrorAction SilentlyContinue

Start-Sleep -Seconds 2

# Reset the bloated Desktop GUI store, but keep a backup.
$desktopDir = Join-Path $env:APPDATA "ai.opencode.desktop"
$store = Join-Path $desktopDir "opencode.global.dat"

if (Test-Path $store) {
  Rename-Item -LiteralPath $store -NewName "opencode.global.dat.$stamp.bak"
  Write-Host "Backed up GUI store: opencode.global.dat.$stamp.bak"
}

Get-ChildItem -Path $desktopDir -Filter "opencode.global.dat.tmp-*" -ErrorAction SilentlyContinue |
  Remove-Item -Force -ErrorAction SilentlyContinue

# Create/update OpenCode global config for OpenRouter timeout.
$cfgDir = Join-Path $env:APPDATA "opencode"
$cfg = Join-Path $cfgDir "opencode.json"

New-Item -ItemType Directory -Force -Path $cfgDir | Out-Null

if (Test-Path $cfg) {
  Copy-Item -LiteralPath $cfg -Destination "$cfg.$stamp.bak" -Force
  $data = Get-Content -LiteralPath $cfg -Raw | ConvertFrom-Json
} else {
  $data = [pscustomobject]@{}
}

function Set-Prop($obj, [string]$name, $value) {
  if ($obj.PSObject.Properties[$name]) {
    $obj.PSObject.Properties[$name].Value = $value
  } else {
    $obj | Add-Member -NotePropertyName $name -NotePropertyValue $value
  }
}

function Ensure-Obj($obj, [string]$name) {
  if (-not $obj.PSObject.Properties[$name] -or $null -eq $obj.PSObject.Properties[$name].Value) {
    Set-Prop $obj $name ([pscustomobject]@{})
  }
  return $obj.PSObject.Properties[$name].Value
}

Set-Prop $data '$schema' 'https://opencode.ai/config.json'
$provider = Ensure-Obj $data 'provider'
$openrouter = Ensure-Obj $provider 'openrouter'
$options = Ensure-Obj $openrouter 'options'

Set-Prop $options 'timeout' $false
Set-Prop $options 'chunkTimeout' $chunkTimeoutMs

$data | ConvertTo-Json -Depth 32 | Set-Content -LiteralPath $cfg -Encoding UTF8

Write-Host "Done. OpenRouter chunkTimeout set to $chunkTimeoutMs ms."
Write-Host "Restart OpenCode."


This PS1 script slash chunk should help with the caching issues that makes the GUI feel really laggy especially for me and also the time out
